/* ===== Quarterly Inspection module v0.7.0 =====
   Kept in a separate local store so the established Check-In/Out, Command-Directed,
   and Furniture record schemas remain unchanged. */
const Q_KEY=APP_KEY+'-quarterly-v1';
const Q_FAIL=[
 'Inoperable electronic lock / compromised door hardware',
 'Candles, incense, or open-flame device',
 'Smoke detector / fire alarm tampered, missing, or inoperable',
 'Fire egress obstruction',
 'Unauthorized kitchen appliance',
 'Daisy-chained power strips / extension cords',
 'High-draw appliance connected through extension cord / power strip',
 'Unauthorized space heater',
 'Inoperable / missing ceiling light fixture',
 'Dryer exhaust hose disconnected / improperly vented',
 'Severe housekeeping creating fire, sanitation, or biological hazard',
 'Excessive clutter / gear blocking pathway or creating trip hazard',
 'Unauthorized room modification'
];
const Q_NONFAIL=[
 'Inoperable window',
 'Broken / missing HVAC diffuser or register',
 'Inoperable range hood exhaust fan',
 'Inoperable dehumidifier',
 'Clogged sink / slow drain',
 'Compromised / stained ceiling tile',
 'Damaged drywall / minor wall abrasion',
 'Normal-wear cosmetic wall / floor discrepancy',
 'Minor / light housekeeping discrepancy'
];
const Q_DEFAULT_TYPES=['Bedroom','Common Bathroom','Lounge / Common Area','Laundry Room','Linen Closet','Janitor Closet','Storage Room','Office','Mechanical / Utility Room','Other'];
function qEmpty(){return{schemaVersion:1,spaceTypes:[...Q_DEFAULT_TYPES],buildings:{},cycles:[],inspections:[],workOrders:[],lastBackup:''}}
function qLoad(){try{return{...qEmpty(),...(JSON.parse(localStorage.getItem(Q_KEY))||{})}}catch{return qEmpty()}}
let qstate=qLoad(),qscreen='dashboard',qcycleId='',qspaceId='',qeditId='',qEditBuilding='';
function qSave(){localStorage.setItem(Q_KEY,JSON.stringify(qstate))}
function qCycle(){return qstate.cycles.find(x=>x.id===qcycleId)||qstate.cycles[0]||null}
function qBuilding(c){return c?qstate.buildings[c.building]:null}
function qResult(fails,nonfails){return fails.length?'FAIL':nonfails.length?'PASS W/CONDITION':'PASS'}
function qSpaceLabel(s){return s?.designation||s?.name||''}
function qLoc(building,space){const raw=qSpaceLabel(space);return /^\d+$/.test(raw)?`${state.settings.installationCode||'FT'}${building}-${raw}`:`${state.settings.installationCode||'FT'}${building}-${raw}`}
function qFYDefault(){const d=new Date(),y=d.getMonth()>=9?d.getFullYear()+1:d.getFullYear();return`FY${String(y).slice(-2)}`}
function qQuarterDefault(){const m=new Date().getMonth()+1;return m>=10?'Q1':m<=3?'Q2':m<=6?'Q3':'Q4'}
function qStats(c){if(!c)return{};const b=qBuilding(c),spaces=(b?.spaces||[]).filter(x=>x.active!==false),target=c.spaceIds?.length?spaces.filter(x=>c.spaceIds.includes(x.id)):spaces,ins=qstate.inspections.filter(x=>x.cycleId===c.id),done=new Set(ins.map(x=>x.spaceId)).size;return{target,ins,required:target.length,done,remaining:Math.max(0,target.length-done),pass:ins.filter(x=>x.result==='PASS').length,cond:ins.filter(x=>x.result==='PASS W/CONDITION').length,fail:ins.filter(x=>x.result==='FAIL').length,wo:qstate.workOrders.filter(x=>x.cycleId===c.id)}}
function quarterlyView(){if(qscreen==='inventory')return qInventoryView();if(qscreen==='inspect')return qInspectView();if(qscreen==='cycle')return qCycleView();return qDashboardView()}
function qDashboardView(){const cycles=[...qstate.cycles].sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));return`<div class="page-head"><div><h2>Quarterly Inspection</h2><p>20% / 100% program · fast room entry · 60-day milestone tracking.</p></div><div class="actions"><button class="button compact" data-action="q-new-cycle">New Cycle</button><button class="button compact secondary" data-action="q-inventory">Building Inventory</button></div></div>${cycles.length?cycles.map(c=>{const s=qStats(c),pct=s.required?Math.round(s.done/s.required*100):0;return`<div class="card q-cycle"><div class="page-head compact-head"><div><span class="badge">${esc(c.scope)} · ${esc(c.fy)} ${esc(c.quarter)}</span><h2>Building ${esc(c.building)}</h2><p>${esc(c.inspector)} · ${fmtDate(c.startDate)}</p></div><button class="button compact" data-action="q-open-cycle" data-id="${c.id}">Open</button></div><div class="q-kpis"><b>${s.done}/${s.required}<small> inspected</small></b><b>${s.remaining}<small> remaining</small></b><b>${s.fail}<small> fail</small></b><b>${s.wo.filter(w=>w.status!=='Closed').length}<small> open WO</small></b></div><div class="progress"><i style="width:${pct}%"></i></div></div>`}).join(''):'<div class="card empty">No quarterly cycles yet. Configure a building, then start a 20% or 100% cycle.</div>'}`}
function qInventoryView(){
 const bs=Object.values(qstate.buildings).sort((a,b)=>a.number.localeCompare(b.number,undefined,{numeric:true}));
 const edit=qEditBuilding?qstate.buildings[qEditBuilding]:null;
 const buildings=buildingList();
 const counts={};
 if(edit) for(const sp of (edit.spaces||[]).filter(x=>x.active!==false&&x.type!=='Bedroom')) counts[sp.type]=(counts[sp.type]||0)+1;
 const ranges=edit?.bedroomRanges||'';
 const qtyTypes=['Laundry Room','Common Bathroom','Lounge / Common Area','Linen Closet','Janitor Closet','Storage Room','Office','Mechanical / Utility Room','Other'];
 return`<div class="page-head"><div><h2>Building & Space Inventory</h2><p>Select a loaded building, enter its bedroom ranges, and the quantity of other spaces.</p></div><button class="button compact outline" data-action="q-dashboard">Back</button></div>
 <div class="card"><h3>${edit?'Edit':'Configure'} Building Inventory</h3><div class="form-grid">
 <div class="field"><label>Building</label><select id="qBldgNo"><option value="">Select building</option>${buildings.map(x=>`<option value="${esc(x)}" ${String(edit?.number||'')===String(x)?'selected':''}>${esc(x)}</option>`).join('')}</select></div>
 <div class="field"><label>Assigned BM</label><input id="qBldgBM" list="qManagerList" value="${esc(edit?.assignedBM||state.settings.inspector)}"><datalist id="qManagerList">${managerList().map(x=>`<option value="${esc(x)}">`).join('')}</datalist><p class="small muted">Auto-fills from Settings; you can override it.</p></div>
 <div class="field full"><label>Bedroom / Room Ranges</label><input id="qBedroomRanges" value="${esc(ranges)}" placeholder="101-134, 201-234, 301-334, 401-434"><p class="small muted">Separate each range with a comma. Gaps are fine: 101-115, 117-134, 201-234.</p></div>
 <div class="field full"><label>Other Spaces — enter quantity only</label><div class="q-qty-grid">${qtyTypes.map(t=>`<label><span>${esc(t)}</span><input type="number" min="0" inputmode="numeric" data-q-space-qty="${esc(t)}" value="${counts[t]||0}"></label>`).join('')}</div></div>
 <div class="field full"><div class="actions"><button class="button" data-action="q-save-building">Save Building Inventory</button>${edit?'<button class="button outline" data-action="q-cancel-building-edit">Cancel Edit</button>':''}</div></div></div></div>
 ${bs.map(b=>{const active=(b.spaces||[]).filter(x=>x.active!==false),bed=active.filter(x=>x.type==='Bedroom').length,common=active.length-bed;return`<div class="card"><div class="page-head compact-head"><div><h3>Building ${esc(b.number)}</h3><p>${esc(b.assignedBM||'')} · ${bed} bedrooms · ${common} common/support · ${active.length} total</p></div><div class="actions"><button class="button compact" data-action="q-edit-building" data-id="${esc(b.number)}">Edit</button><button class="button compact secondary" data-action="q-export-building" data-id="${esc(b.number)}">Export JSON</button><button class="button compact outline" data-action="q-delete-building" data-id="${esc(b.number)}">Remove</button></div></div><div class="small">Ranges: <b>${esc(b.bedroomRanges||'—')}</b><br>${Object.entries(active.filter(x=>x.type!=='Bedroom').reduce((m,x)=>(m[x.type]=(m[x.type]||0)+1,m),{})).map(([k,v])=>`${esc(k)}: <b>${v}</b>`).join(' · ')||'No common/support spaces configured.'}</div></div>`}).join('')}
 <div class="card"><h3>Building Inventory Import / Export</h3><p class="small muted">Export a single building to share it with another team member. Importing a building JSON adds it or updates the same building number.</p><label class="button secondary" style="cursor:pointer">Import Building JSON<input id="qImportBuilding" type="file" accept="application/json,.json" hidden></label></div>`}
function qNewCycleDialog(){const bs=Object.values(qstate.buildings).filter(b=>(b.spaces||[]).some(s=>s.active!==false));if(!bs.length){qscreen='inventory';render();return}showDialog('New Quarterly Cycle',`<div class="stack"><div class="form-grid"><div class="field"><label>Fiscal Year</label><input id="qcFY" value="${qFYDefault()}"></div><div class="field"><label>Quarter</label><select id="qcQ"><option>Q1</option><option>Q2</option><option>Q3</option><option>Q4</option></select></div><div class="field"><label>Scope</label><select id="qcScope"><option>20%</option><option>100%</option></select></div><div class="field"><label>Building</label><select id="qcBuilding">${bs.map(b=>`<option value="${esc(b.number)}">${esc(b.number)}</option>`).join('')}</select></div><div class="field"><label>Start date / Day 1</label><input id="qcDate" type="date" value="${today()}"></div><div class="field"><label>Lead / BM</label><input id="qcInspector" value="${esc(state.settings.inspector)}"></div></div><p class="small muted">100% starts with all active spaces. For 20%, create the cycle then select the designated spaces from the cycle screen.</p><button class="button full" id="qcCreate">Create Cycle</button></div>`);document.querySelector('#qcQ').value=qQuarterDefault();document.querySelector('#qcBuilding').onchange=e=>{document.querySelector('#qcInspector').value=qstate.buildings[e.target.value]?.assignedBM||state.settings.inspector};document.querySelector('#qcCreate').onclick=()=>{const building=val('qcBuilding'),b=qstate.buildings[building],scope=val('qcScope');const c={id:uid(),fy:val('qcFY'),quarter:val('qcQ'),scope,building,startDate:val('qcDate'),inspector:val('qcInspector'),createdAt:new Date().toISOString(),spaceIds:scope==='100%'?(b.spaces||[]).filter(x=>x.active!==false).map(x=>x.id):[]};qstate.cycles.unshift(c);qSave();qcycleId=c.id;closeDialog();qscreen='cycle';render()}}
function qCycleView(){const c=qCycle();if(!c){qscreen='dashboard';return qDashboardView()}const s=qStats(c),b=qBuilding(c),start=new Date(c.startDate+'T00:00:00'),day=Math.max(1,Math.floor((new Date()-start)/86400000)+1),phase=day<=30?'PHASE 1 · PHYSICAL INSPECTIONS':day<=60?'PHASE 2 · eMH / WO RECONCILIATION':'PAST 60-DAY WINDOW',pct=s.required?Math.round(s.done/s.required*100):0;const all=(b?.spaces||[]).filter(x=>x.active!==false),selected=new Set(c.spaceIds||[]);return`<div class="page-head"><div><span class="badge">${esc(c.scope)} · ${esc(c.fy)} ${esc(c.quarter)}</span><h2>Building ${esc(c.building)}</h2><p>${phase} · Day ${day}</p></div><button class="button compact outline" data-action="q-dashboard">All Cycles</button></div><div class="card"><div class="q-kpis"><b>${s.done}/${s.required}<small> inspected</small></b><b>${s.remaining}<small> remaining</small></b><b>${s.pass}<small> pass</small></b><b>${s.cond}<small> condition</small></b><b>${s.fail}<small> fail</small></b></div><div class="progress"><i style="width:${pct}%"></i></div><div class="actions"><button class="button" data-action="q-next">Inspect Next</button><button class="button secondary" data-action="q-export-excel">Export Quarterly Excel</button></div></div>${c.scope==='20%'?`<div class="card"><h3>20% Designated Spaces</h3><p class="small muted">Select only the official/designated inspection population. The app does not choose the 20% sample for you.</p><div class="q-space-picker">${all.map(x=>`<label><input type="checkbox" data-q-space-select="${x.id}" ${selected.has(x.id)?'checked':''}> ${esc(qSpaceLabel(x))} <span class="muted">${esc(x.type)}</span></label>`).join('')}</div><button class="button compact" data-action="q-save-selection">Save Selection</button></div>`:''}<div class="card"><h3>Spaces</h3>${s.target.length?s.target.map(sp=>{const r=s.ins.filter(x=>x.spaceId===sp.id).slice(-1)[0];return`<div class="record"><span><b>${esc(qSpaceLabel(sp))}</b> <span class="muted">${esc(sp.type)}</span></span><span>${r?`<b>${esc(r.result)}</b> <button class="button compact outline" data-action="q-inspect-space" data-id="${sp.id}">Edit</button>`:`<button class="button compact" data-action="q-inspect-space" data-id="${sp.id}">Inspect</button>`}</span></div>`}).join(''):'<div class="empty">No spaces selected yet.</div>'}</div>`}
function qInspectView(){const c=qCycle(),b=qBuilding(c),sp=(b?.spaces||[]).find(x=>x.id===qspaceId);if(!c||!sp){qscreen='cycle';return qCycleView()}const old=qstate.inspections.find(x=>x.id===qeditId)||qstate.inspections.filter(x=>x.cycleId===c.id&&x.spaceId===sp.id).slice(-1)[0],fails=old?.failCriteria||[],nonfails=old?.nonFailCriteria||[];return`<div class="page-head compact-head"><div><span class="badge">${esc(c.scope)} · ${esc(c.fy)} ${esc(c.quarter)}</span><h2>${esc(qSpaceLabel(sp))}</h2><p>Building ${esc(c.building)} · ${esc(sp.type)} · ${esc(qLoc(c.building,sp))}</p></div><button class="button compact outline" data-action="q-back-cycle">Back</button></div><div class="card q-fast"><h3>Inspection Result</h3><div class="q-big-actions"><button class="button success" data-action="q-pass">✓ PASS & NEXT</button><button class="button danger" data-action="q-deficiency">⚠ DEFICIENCY</button></div><div id="qDefPanel" class="${fails.length||nonfails.length?'':'hidden'}"><div class="q-tabs"><div><h3>FAIL — Critical</h3>${Q_FAIL.map(x=>`<label class="q-check"><input type="checkbox" data-q-fail value="${esc(x)}" ${fails.includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div><div><h3>NON-FAIL</h3>${Q_NONFAIL.map(x=>`<label class="q-check"><input type="checkbox" data-q-nonfail value="${esc(x)}" ${nonfails.includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div></div><div class="field"><label>Inspector comment (optional)</label><input id="qManualComment" value="${esc(old?.manualComment||'')}" placeholder="Only type what the standard criteria do not explain"></div><div class="field"><label class="q-check"><input id="qWO" type="checkbox" ${old?.woRequired?'checked':''}> Work Order Required</label></div><button class="button full" data-action="q-save-def">Save & Next Room</button></div></div>`}
function qSaveInspection(clean=false){const c=qCycle(),b=qBuilding(c),sp=(b?.spaces||[]).find(x=>x.id===qspaceId);if(!c||!sp)return;const fails=clean?[]:[...document.querySelectorAll('[data-q-fail]:checked')].map(x=>x.value),nonfails=clean?[]:[...document.querySelectorAll('[data-q-nonfail]:checked')].map(x=>x.value),manual=clean?'':val('qManualComment'),woRequired=clean?false:!!document.querySelector('#qWO')?.checked,result=qResult(fails,nonfails),existing=qstate.inspections.find(x=>x.id===qeditId)||qstate.inspections.find(x=>x.cycleId===c.id&&x.spaceId===sp.id),rec={id:existing?.id||uid(),cycleId:c.id,date:today(),building:c.building,spaceId:sp.id,space:qSpaceLabel(sp),spaceType:sp.type,location:qLoc(c.building,sp),inspector:c.inspector,result,failCriteria:fails,nonFailCriteria:nonfails,manualComment:manual,woRequired,updatedAt:new Date().toISOString()};if(existing)Object.assign(existing,rec);else qstate.inspections.push(rec);if(woRequired&&!qstate.workOrders.some(w=>w.inspectionId===rec.id))qstate.workOrders.push({id:uid(),cycleId:c.id,inspectionId:rec.id,building:c.building,space:rec.space,deficiency:[...fails,...nonfails].join('; '),manualComment:manual,woNumber:'',status:'Needs Submission',dateSubmitted:'',dateCompleted:''});if(!woRequired)qstate.workOrders=qstate.workOrders.filter(w=>w.inspectionId!==rec.id);qSave();qGoNext(sp.id)}
function qGoNext(current){const c=qCycle(),s=qStats(c),idx=s.target.findIndex(x=>x.id===current),ordered=[...s.target.slice(idx+1),...s.target.slice(0,idx+1)],next=ordered.find(sp=>!qstate.inspections.some(i=>i.cycleId===c.id&&i.spaceId===sp.id));if(next){qspaceId=next.id;qeditId='';qscreen='inspect'}else qscreen='cycle';render()}
function qExportExcel(){const c=qCycle(),s=qStats(c);if(!c)return;const compiled=[['Building','Bedroom','PASS/FAIL','Comments'],...s.ins.map(r=>[r.building,r.location,r.result,[...r.failCriteria,...r.nonFailCriteria,r.manualComment].filter(Boolean).join('; ')])];const detail=[['Building','Space','Space Type','Location','PASS/FAIL','FAIL Criteria','NON-FAIL Criteria','Inspector Comments','WO Required','Inspector','Date'],...s.ins.map(r=>[r.building,r.space,r.spaceType,r.location,r.result,r.failCriteria.join('; '),r.nonFailCriteria.join('; '),r.manualComment,r.woRequired?'Yes':'No',r.inspector,r.date])];const wo=[['Building','Space','Deficiency','Inspector Comments','WO Number','Status','Date Submitted','Date Completed'],...s.wo.map(w=>[w.building,w.space,w.deficiency,w.manualComment,w.woNumber,w.status,w.dateSubmitted,w.dateCompleted])];download(`Quarterly-${c.fy}-${c.quarter}-${c.scope.replace('%','pct')}-Bldg-${c.building}.xlsx`,buildXlsx([{name:'COMPILED RESULTS',rows:compiled},{name:'INSPECTION DETAIL',rows:detail},{name:'WORK ORDERS REQUIRED',rows:wo}]))}
function qSaveBuilding(){
 const number=val('qBldgNo');if(!number)return showDialog('Building required','Select a building from Settings.');
 const rawRanges=val('qBedroomRanges').trim(),tokens=rawRanges.split(',').map(x=>x.trim()).filter(Boolean),wanted=[];
 for(const token of tokens){const m=token.match(/^(\d+)\s*-\s*(\d+)$/);if(m){const a=+m[1],z=+m[2];if(z<a)return showDialog('Room range','Check this range: '+token);for(let n=a;n<=z;n++)wanted.push(String(n))}else if(/^\d+$/.test(token))wanted.push(token);else return showDialog('Room range','Use ranges such as 101-134, 201-234. Check: '+token)}
 const old=qstate.buildings[number],oldSpaces=old?.spaces||[],spaces=[];
 const reuse=(type,designation)=>oldSpaces.find(x=>x.type===type&&x.designation===designation);
 [...new Set(wanted)].forEach(designation=>{const o=reuse('Bedroom',designation);spaces.push(o?{...o,active:true}:{id:uid(),deck:Number(designation[0])||1,type:'Bedroom',designation,active:true})});
 document.querySelectorAll('[data-q-space-qty]').forEach(inp=>{const type=inp.dataset.qSpaceQty,qty=Math.max(0,Number(inp.value)||0);for(let i=1;i<=qty;i++){const designation=`${type} ${i}`,o=reuse(type,designation);spaces.push(o?{...o,active:true}:{id:uid(),deck:0,type,designation,active:true})}});
 qstate.buildings[number]={number,assignedBM:val('qBldgBM')||assignedManager(number),bedroomRanges:rawRanges,spaces};qEditBuilding='';qSave();render()
}
function qExportBuilding(number){const b=qstate.buildings[number];if(b)download(`${state.settings.installationCode||'FT'}-${number}-BuildingConfig.json`,new Blob([JSON.stringify({schemaVersion:1,type:'UHBuildingConfig',building:b},null,2)],{type:'application/json'}))}
async function qImportBuilding(file){if(!file)return;try{const data=JSON.parse(await file.text()),b=data.building||data;if(!b.number||!Array.isArray(b.spaces))throw Error();qstate.buildings[b.number]=b;qSave();render()}catch{showDialog('Import failed','That file is not a valid building configuration backup.')}}
function exportFullBackup(){qstate.lastBackup=new Date().toISOString();qSave();download(`UH-field-app-full-backup-${today()}.json`,new Blob([JSON.stringify({backupType:'UHFieldAppFull',schemaVersion:1,appVersion:APP_VERSION,core:state,quarterly:qstate},null,2)],{type:'application/json'}))}
async function restoreFullBackup(file){if(!file)return;try{const data=JSON.parse(await file.text());if(data.backupType==='UHFieldAppFull'){state={...emptyState(),...(data.core||{})};qstate={...qEmpty(),...(data.quarterly||{})}}else{state={...emptyState(),...data}}save();qSave();showDialog('Backup restored','Core inspection records and Quarterly data were restored.');render()}catch{showDialog('Restore failed','The selected JSON file could not be restored.')}}
function bindQuarterly(){const imp=document.querySelector('#qImportBuilding');if(imp)imp.onchange=e=>qImportBuilding(e.target.files?.[0]);const b=document.querySelector('#qBldgNo'),bm=document.querySelector('#qBldgBM');if(b&&bm)b.onchange=()=>{bm.value=assignedManager(b.value)||state.settings.inspector};document.querySelectorAll('[data-q-space-select]').forEach(x=>x.onchange=()=>{})}
const _coreAction=action;
action=function(name,id){
 if(name==='q-dashboard'){qscreen='dashboard';route='quarterly';return render()}
 if(name==='q-inventory'){qscreen='inventory';route='quarterly';return render()}
 if(name==='q-new-cycle')return qNewCycleDialog()
 if(name==='q-open-cycle'){qcycleId=id;qscreen='cycle';return render()}
 if(name==='q-save-building')return qSaveBuilding()
 if(name==='q-edit-building'){qEditBuilding=id;qscreen='inventory';return render()}
 if(name==='q-cancel-building-edit'){qEditBuilding='';return render()}
 if(name==='q-export-building')return qExportBuilding(id)
 if(name==='q-delete-building'){if(confirm(`Remove Building ${id} configuration? Existing inspection records are retained.`)){delete qstate.buildings[id];qSave();render()}return}
 if(name==='q-save-selection'){const c=qCycle();c.spaceIds=[...document.querySelectorAll('[data-q-space-select]:checked')].map(x=>x.dataset.qSpaceSelect);qSave();return render()}
 if(name==='q-inspect-space'){qspaceId=id;const c=qCycle(),old=qstate.inspections.find(x=>x.cycleId===c.id&&x.spaceId===id);qeditId=old?.id||'';qscreen='inspect';return render()}
 if(name==='q-next'){const c=qCycle(),s=qStats(c),next=s.target.find(sp=>!qstate.inspections.some(i=>i.cycleId===c.id&&i.spaceId===sp.id));if(!next)return showDialog('Cycle complete','All selected spaces have an inspection record.');qspaceId=next.id;qeditId='';qscreen='inspect';return render()}
 if(name==='q-back-cycle'){qscreen='cycle';return render()}
 if(name==='q-deficiency'){document.querySelector('#qDefPanel')?.classList.remove('hidden');return}
 if(name==='q-pass')return qSaveInspection(true)
 if(name==='q-save-def')return qSaveInspection(false)
 if(name==='q-export-excel')return qExportExcel()
 return _coreAction(name,id)
}
